package com.shikshasetu.ai;
import org.apache.commons.csv.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import weka.classifiers.Evaluation;import weka.classifiers.trees.RandomForest;import weka.core.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.Instant;import java.time.ZoneOffset;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.stream.Collectors;
@Service public class AiModelTrainingService {
 public static final String TARGET="1 = the next reporting-period subject-average mark falls by at least 10 percentage points versus the current-period average; 0 = it does not.";
 private static final List<String> FEATURES=List.of("attendance_percent","internal_marks_percent","assignment_completion_percent","previous_failures","absence_count","consecutive_absences","recent_mark_drop","repeated_low_results");
 private static final List<String> HEADERS=List.of("student_key", "attendance_percent","internal_marks_percent","assignment_completion_percent","previous_failures","absence_count","consecutive_absences","recent_mark_drop","repeated_low_results","next_period_deterioration");
 private final Path modelPath;private final AiModelRuntime runtime;
 public AiModelTrainingService(@Value("${shikshasetu.ai.model-path:./data/ai-models/student-deterioration.model}") String p,AiModelRuntime r){modelPath=Paths.get(p).toAbsolutePath().normalize();runtime=r;}
 public synchronized AiTrainingResult train(MultipartFile file){if(file==null||file.isEmpty())throw new IllegalArgumentException("Upload a non-empty labelled CSV.");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("CSV must be 10 MB or smaller.");try{List<Row> rows=parse(file.getInputStream());Set<String> keys=rows.stream().map(Row::key).collect(Collectors.toSet());if(keys.size()<30)throw new IllegalArgumentException("At least 30 distinct pseudonymous student_key values are required for this prototype.");Instances all=instances(rows);Split split=split(rows,all);checkClasses(split.train);checkClasses(split.test);RandomForest validation=forest();validation.buildClassifier(split.train);Evaluation eval=new Evaluation(split.train);eval.evaluateModel(validation,split.test);double[][] cm=eval.confusionMatrix();int tn=(int)cm[0][0],fp=(int)cm[0][1],fn=(int)cm[1][0],tp=(int)cm[1][1];double precision=ratio(tp,tp+fp),recall=ratio(tp,tp+fn),f1=precision+recall==0?0:2*precision*recall/(precision+recall);TrainingMetrics metrics=new TrainingMetrics(rows.size(),keys.size(),split.train.numInstances(),split.test.numInstances(),tp,tn,fp,fn,ratio(tp+tn,tp+tn+fp+fn),precision,recall,f1,finite(eval.areaUnderROC(1)),"Grouped 80/20 holdout by student_key; seed=42. Temporal/external validation is still required.");RandomForest finalModel=forest();finalModel.buildClassifier(all);String version="ss-rf-"+DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss").withZone(ZoneOffset.UTC).format(Instant.now());ModelBundle bundle=new ModelBundle(finalModel,new Instances(all,0),version,Instant.now(),metrics);Files.createDirectories(modelPath.getParent());SerializationHelper.write(modelPath.toString(),bundle);runtime.install(bundle);return new AiTrainingResult("TRAINED_PROTOTYPE",version,bundle.getTrainedAt().toString(),TARGET,metrics,"Not approved for operational decisions. Validate on later terms/cohorts and review subgroup errors and calibration.");}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("Training failed: "+e.getMessage(),e);}}
 private List<Row> parse(InputStream in)throws IOException{List<Row> rows=new ArrayList<>();try(Reader reader=new InputStreamReader(in,StandardCharsets.UTF_8);CSVParser parser=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).setTrim(true).build().parse(reader)){if(!parser.getHeaderMap().keySet().containsAll(HEADERS))throw new IllegalArgumentException("Missing CSV columns. Required headers: "+String.join(",",HEADERS));for(CSVRecord r:parser){String key=r.get("student_key").trim();if(key.isBlank())throw new IllegalArgumentException("student_key cannot be blank");double[] x=new double[8];for(int i=0;i<8;i++){String raw=r.get(FEATURES.get(i)).trim();x[i]=(raw.isBlank()||raw.equals("?"))?Double.NaN:Double.parseDouble(raw);}validate(x);String y=r.get("next_period_deterioration").trim();if(!y.equals("0")&&!y.equals("1"))throw new IllegalArgumentException("next_period_deterioration must be 0 or 1");rows.add(new Row(key,x,Integer.parseInt(y)));}}if(rows.size()<100)throw new IllegalArgumentException("At least 100 labelled snapshots are required by this prototype guard; this is not a claim that 100 is statistically sufficient.");return rows;}
 private void validate(double[] x){range(x[0],100,"attendance_percent");range(x[1],100,"internal_marks_percent");range(x[2],100,"assignment_completion_percent");range(x[3],100,"previous_failures");range(x[4],1000,"absence_count");range(x[5],100,"consecutive_absences");range(x[6],100,"recent_mark_drop");range(x[7],100,"repeated_low_results");}
 private void range(double x,double max,String name){if(Double.isNaN(x))return;if(!Double.isFinite(x)||x<0||x>max)throw new IllegalArgumentException(name+" must be missing or between 0 and "+max);}
 private Instances instances(List<Row> rows){ArrayList<Attribute> a=new ArrayList<>();FEATURES.forEach(n->a.add(new Attribute(n)));a.add(new Attribute("next_period_deterioration",List.of("0","1")));Instances data=new Instances("shikshasetu_deterioration",a,rows.size());data.setClassIndex(data.numAttributes()-1);for(Row r:rows){double[] v=Arrays.copyOf(r.x,9);v[8]=r.y;data.add(new DenseInstance(1,v));}return data;}
 private Split split(List<Row> rows,Instances all){List<String> keys=rows.stream().map(Row::key).distinct().collect(Collectors.toCollection(ArrayList::new));Collections.shuffle(keys,new Random(42));Set<String> testKeys=new HashSet<>(keys.subList(0,Math.max(1,(int)Math.round(keys.size()*.20))));Instances tr=new Instances(all,0),te=new Instances(all,0);for(int i=0;i<rows.size();i++)(testKeys.contains(rows.get(i).key)?te:tr).add(all.instance(i));return new Split(tr,te);}
 private void checkClasses(Instances d){int a=0,b=0;for(Instance i:d){if((int)i.classValue()==0)a++;else b++;}if(a<5||b<5)throw new IllegalArgumentException("Both target classes need at least five examples in train and holdout sets. Collect more balanced longitudinal data.");}
 private RandomForest forest()throws Exception{RandomForest f=new RandomForest();f.setOptions(new String[]{"-I","300","-K","0","-M","5","-S","42","-depth","8"});return f;}
 private double ratio(double a,double b){return b==0?0:a/b;}private double finite(double x){return Double.isFinite(x)?x:0;}
 public AiModelStatus status(){Optional<ModelBundle> o=runtime.current();if(o.isEmpty())return new AiModelStatus("Weka Random Forest","NOT_TRAINED",null,null,null,TARGET,"No trained model artifact. Existing baseline endpoint is unchanged.");ModelBundle b=o.get();return new AiModelStatus("Weka Random Forest","TRAINED_PROTOTYPE",b.getModelVersion(),b.getTrainedAt().toString(),b.getMetrics(),TARGET,"Research prototype only; human review required.");}
 private record Row(String key,double[] x,int y){}private record Split(Instances train,Instances test){}
}
